def bisect(f,lo,hi,tol=1e-6):
    count=0
    while hi-lo>tol:
        mid=(lo+hi)/2
        if f(mid)*f(lo)>0:
            lo=mid
        else:
            hi=mid
        count+=1
    return (lo+hi)/2,count
